<body>
<div class="wrap">
  <h1>Kitchen Unit Converter</h1>
  <p class="lead">Type an amount, pick your units, and get the result instantly. Conversions are saved automatically.</p>

  <div class="card">
    <div class="grid two">
      <div>
        <label for="amount">Amount</label>
        <input id="amount" type="number" inputmode="decimal" step="any" placeholder="0" autocomplete="off">
      </div>
      <button class="btn sec swap" id="swap" type="button" aria-label="Swap the two units">&#8646; Swap</button>
      <div>
        <label for="from">From</label>
        <select id="from"></select>
      </div>
    </div>
    <div class="grid" style="margin-top:14px">
      <div>
        <label for="to">To</label>
        <select id="to"></select>
      </div>
    </div>
    <div class="out">
      <div class="big" id="result"><span class="empty">Enter an amount to convert</span></div>
      <div class="sub" id="detail"></div>
      <div class="err" id="err"></div>
    </div>
    <p class="hint" id="hint"></p>
  </div>

  <div class="card">
    <h2 class="sec-title">Common conversions</h2>
    <div class="conv-list" id="convList"></div>
    <p class="note">Weight-to-volume conversions use water (1&nbsp;g&nbsp;=&nbsp;1&nbsp;mL). For flour, sugar, or butter the volume will differ. US measures: 1&nbsp;cup&nbsp;=&nbsp;240&nbsp;mL, 1&nbsp;tbsp&nbsp;=&nbsp;15&nbsp;mL, 1&nbsp;tsp&nbsp;=&nbsp;5&nbsp;mL. 1&nbsp;dl&nbsp;=&nbsp;100&nbsp;mL.</p>
  </div>

  <div class="sr" id="live" role="status" aria-live="polite"></div>
</div>

<script>
(function(){
  var UNITS = {
    g:   {name:'Grams',            cat:'weight', ml:1},
    kg:  {name:'Kilograms',        cat:'weight', ml:1000},
    oz:  {name:'Ounces (weight)',  cat:'weight', ml:28.3495},
    lb:  {name:'Pounds (weight)',  cat:'weight', ml:453.592},
    ml:  {name:'Millilitres',      cat:'volume', ml:1},
    dl:  {name:'Decilitres',       cat:'volume', ml:100},
    l:   {name:'Litres',           cat:'volume', ml:1000},
    cup: {name:'Cups (US)',        cat:'volume', ml:240},
    tbsp:{name:'Tablespoons (US)', cat:'volume', ml:15},
    tsp: {name:'Teaspoons (US)',   cat:'volume', ml:5},
    fl:  {name:'Fluid ounces (US)',cat:'volume', ml:29.5735}
  };

  var amount = document.getElementById('amount');
  var fromSel = document.getElementById('from');
  var toSel = document.getElementById('to');
  var result = document.getElementById('result');
  var detail = document.getElementById('detail');
  var err = document.getElementById('err');
  var hint = document.getElementById('hint');
  var live = document.getElementById('live');

  function buildOptions(sel){
    Object.keys(UNITS).forEach(function(k){
      var o = document.createElement('option');
      o.value = k; o.textContent = UNITS[k].name;
      sel.appendChild(o);
    });
  }
  buildOptions(fromSel); buildOptions(toSel);
  fromSel.value = 'g'; toSel.value = 'cup';

  function fmt(n){
    if(!isFinite(n)) return '—';
    var r = Math.round(n*1000)/1000;
    return r.toLocaleString('en-US',{maximumFractionDigits:3});
  }

  function convert(){
    var val = parseFloat(amount.value);
    var f = fromSel.value, t = toSel.value;
    err.textContent = '';
    if(amount.value === '' || isNaN(val)){
      result.innerHTML = '<span class="empty">Enter an amount to convert</span>';
      detail.textContent = ''; hint.textContent = '';
      return;
    }
    if(val < 0){ err.textContent = 'Enter a positive amount.'; return; }
    var ratio = UNITS[f].ml / UNITS[t].ml;
    var out = val * ratio;
    result.textContent = fmt(out) + ' ' + UNITS[t].name;
    detail.textContent = fmt(val) + ' ' + UNITS[f].name + ' = ' + fmt(out) + ' ' + UNITS[t].name;

    var note = '';
    if(UNITS[f].cat !== UNITS[t].cat){
      note = 'Weight ↔ volume uses water density (1 g = 1 mL). Adjust for other ingredients.';
    } else if(UNITS[f].cat === 'volume'){
      note = 'Volume-to-volume conversion — accurate for any ingredient.';
    } else {
      note = 'Weight-to-weight conversion — accurate for any ingredient.';
    }
    hint.textContent = note;
    live.textContent = fmt(val) + ' ' + UNITS[f].name + ' equals ' + fmt(out) + ' ' + UNITS[t].name;
    save();
  }

  function swap(){
    var a = fromSel.value; fromSel.value = toSel.value; toSel.value = a;
    convert();
  }

  // Common conversions list
  var COMMON = [
    ['1 cup', '240 mL', '1 cup (US) = 240 mL'],
    ['1 tbsp', '15 mL', '1 tablespoon = 15 mL'],
    ['1 tsp', '5 mL', '1 teaspoon = 5 mL'],
    ['1 dl', '100 mL', '1 decilitre = 100 mL'],
    ['1 lb', '453.6 g', '1 pound = 453.6 grams'],
    ['1 oz', '28.3 g', '1 ounce (weight) = 28.3 grams'],
    ['1 fl oz', '29.6 mL', '1 fluid ounce = 29.6 mL'],
    ['1 kg', '1000 g', '1 kilogram = 1000 grams']
  ];
  var convList = document.getElementById('convList');
  COMMON.forEach(function(row){
    var el = document.createElement('div');
    el.className = 'conv-row';
    var k = document.createElement('span'); k.className='k'; k.textContent = row[0] + ' =';
    var v = document.createElement('span'); v.className='v'; v.textContent = row[1];
    var c = document.createElement('button'); c.className='copy'; c.type='button'; c.textContent='Copy';
    c.setAttribute('aria-label', 'Copy ' + row[2]);
    c.addEventListener('click', function(){
      var txt = row[2];
      if(navigator.clipboard && navigator.clipboard.writeText){
        navigator.clipboard.writeText(txt).then(function(){
          c.textContent='Copied'; live.textContent = txt + ' copied';
          setTimeout(function(){c.textContent='Copy';},1200);
        });
      } else { c.textContent='Copied'; live.textContent = txt + ' copied';
        setTimeout(function(){c.textContent='Copy';},1200); }
    });
    el.appendChild(k); el.appendChild(v); el.appendChild(c);
    convList.appendChild(el);
  });

  // Persistence
  var KEY = 'kitchen-converter';
  function save(){
    if(window.alfy && window.alfy.storage){
      window.alfy.storage.set(KEY, {amount:amount.value, from:fromSel.value, to:toSel.value});
    }
  }
  function load(){
    if(window.alfy && window.alfy.storage){
      window.alfy.storage.get(KEY).then(function(v){
        if(v){
          if(typeof v.amount === 'string') amount.value = v.amount;
          if(UNITS[v.from]) fromSel.value = v.from;
          if(UNITS[v.to]) toSel.value = v.to;
          convert();
        }
      }).catch(function(){});
    }
  }

  amount.addEventListener('input', convert);
  fromSel.addEventListener('change', convert);
  toSel.addEventListener('change', convert);
  document.getElementById('swap').addEventListener('click', swap);

  convert();
  load();
})();
</script>
</body>
</html>
